\draw[midarrow, dashed] (P) -- (Q) node[pos=0.3, fill=white, inner sep=1pt] {$0$} node[pos=0.72, right, font=\small] {dummy};
\draw[midarrow] (P) -- (R) node[pos=0.35, fill=white, inner sep=1pt] {$C,\,3$};
\draw[midarrow] (Q) -- (T) node[pos=0.35, fill=white, inner sep=1pt] {$D,\,8$};
